tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/3c-capture-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
$PY -c "import storygame,sys; sys.exit(0 if storygame.__file__.startswith('$PWD') else 1)" || { echo "FAIL: not worktree"; exit 1; }
bad=$(git status --porcelain | awk '{print $2}' | grep -v -x -e notes.md -e pytest.out -e scripts/ringer/stage7/three_c_probe.py -e scripts/ringer/stage7/check_three_c_probe.py -e tests/test_3c_item_facts_capture.py)
test -z "$bad" || { echo "FAIL: outside ownership: $bad"; exit 1; }
git diff --quiet -- storygame data || { echo "FAIL: storygame/data edited"; exit 1; }
$PY -m pytest -q --no-cov -p no:cacheprovider tests/test_3c_item_facts_capture.py tests/test_3c_kristin_place.py tests/test_3c_carried_start.py tests/test_3c_escape_result.py tests/test_3c_custody_result.py tests/test_3c_entry_package.py tests/test_3c_pump_need.py > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
rm -rf /tmp/cap-dry; $PY scripts/ringer/stage7/three_c_probe.py --n 1 --mode play --start postc --arms control --kristin-place facility_escape --capture-item-facts --first-command 'Follow Michelle and the captives through the surface gates.' --semantic on --dry-run --out /tmp/cap-dry >/dev/null || exit 1
$PY scripts/ringer/stage7/check_three_c_probe.py /tmp/cap-dry 1 --mode dry || exit 1
rm -rf /tmp/cap-off; $PY scripts/ringer/stage7/three_c_probe.py --n 1 --mode play --start postc --arms control --first-command 'Follow Michelle and the captives through the surface gates.' --semantic on --dry-run --out /tmp/cap-off >/dev/null && grep -q capture_item_facts /tmp/cap-off/source.json /tmp/cap-off/plan.json && { echo "FAIL: flag-off artifacts carry capture_item_facts"; exit 1; }
$PY -m ruff check scripts/ringer/stage7 tests/test_3c_item_facts_capture.py && $PY -m ruff format --check scripts/ringer/stage7 tests/test_3c_item_facts_capture.py || exit 1
git add -A -- scripts tests && git diff --cached -- scripts tests > /home/bcorfman/dev/ringer-work/3c-capture.patch && test -s /home/bcorfman/dev/ringer-work/3c-capture.patch && echo "patch exported"
